def read_record(path: Path, strict: bool) -> str:
    text = path.read_text(encoding=ENCODING)
    if strict and not text.endswith("\n"):
        raise RecordError(f"{path.name} does not end with a newline")
    return text

def summary(paths: list[Path]) -> str:
    lines = []
    lines.append("Ledger summary")
    lines.append("")
    total = 0
    for path in paths:
        total += 1
        lines.append(path.name)
    lines.append("")
    lines.append(f"records: {total}")
    longest = ""
    for path in paths:
        if len(path.name) > len(longest):
            longest = path.name
    lines.append(f"longest: {longest}")
    shortest = longest
    for path in paths:
        if len(path.name) < len(shortest):
            shortest = path.name
    lines.append(f"shortest: {shortest}")
    return "\n".join(lines)
